import { Component, ComponentInterface, Element, h, Prop, Watch } from '@stencil/core';

/**
 * @slot default - default slot for anchor item content
 */
@Component({
  tag: 'groupui-anchor-item',
  styleUrl: 'anchor-item.scss',
  shadow: true,
})
export class AnchorItem implements ComponentInterface {
  /**
   * Sets the anchor item as selected.
   */
  @Prop({ reflect: true }) readonly selected: boolean;

  /**
   * Reference ID for the anchor item.
   */
  @Prop({ reflect: true }) readonly idRef: string;

  /**
   * Nesting level of the anchor item.
   */
  @Prop({ reflect: true }) readonly nestingLevel: number = 0;

  /**
   * Descriptive text which will be displayed in a tag element next to the component
   */
  @Prop({ reflect: true }) readonly tag: string;

  @Element() host: HTMLElement;

  componentWillLoad() {
    this.setNestingLevelCssVariable();
  }

  @Watch('nestingLevel')
  onNestingLevelChanged() {
    this.setNestingLevelCssVariable();
  }

  private setNestingLevelCssVariable() {
    this.host.style.setProperty('--nesting-level', this.nestingLevel.toString());
  }

  render() {
    return (
      <a href={`#${this.idRef}`} tabIndex={0}>
        <div id="anchor-item-link-text">
          <slot></slot>
        </div>
        {this.tag && (
          <groupui-tag variant="tertiary" color="neutral">
            {this.tag}
          </groupui-tag>
        )}
      </a>
    );
  }
}
